const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const templateKey = String(body.templateKey ?? '').trim();
if (!templateKey) {
  throw new Error('templateKey is required');
}

const templateInstructions = String(body.templateInstructions ?? '').trim();
const promptText = String(body.promptText ?? '').trim();
if (!promptText) {
  throw new Error('promptText is required');
}

const eventHint = body.eventHint ? String(body.eventHint).trim() : null;
const procedureLabel = body.procedureLabel ? String(body.procedureLabel).trim() : null;
const identity = body.identity && typeof body.identity === 'object' ? body.identity : {};

const system =
  'You write short first-person social posts as a pet on Petsbook.\n' +
  'Produce TWO independent texts (not a translation of each other): one English, one French (natural Canadian/European French).\n' +
  'Rules:\n' +
  '- Never mention AI, language models, prompts, or being artificial.\n' +
  '- Speak as the pet (I / me / je / moi).\n' +
  '- Follow the template instructions carefully.\n' +
  '- Use only facts from the provided context. Do not invent friends, awards, or medical details.\n' +
  '- Each text under 800 characters.\n' +
  '- Return ONLY valid JSON with exactly these keys (no markdown):\n' +
  '{"body":"<English text>","bodyFr":"<French text>"}';

const userPayload = {
  templateKey,
  templateInstructions,
  eventHint,
  procedureLabel,
  identity,
  context: promptText,
};

const openAiBody = {
  model: 'gpt-4o-mini',
  temperature: 0.85,
  max_tokens: 700,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    {
      role: 'user',
      content:
        'Write both texts from this Petsbook context (JSON):\n' +
        JSON.stringify(userPayload, null, 2),
    },
  ],
};

return [{ json: { templateKey, openAiBody } }];

const content = String(
  $input.first().json.choices?.[0]?.message?.content ?? '',
)
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '');

if (!content) {
  throw new Error('OpenAI returned empty draft payload');
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  throw new Error('OpenAI returned non-JSON draft payload');
}

function clean(value) {
  return String(value ?? '')
    .trim()
    .replace(/^[\"'«»]+|[\"'«»]+$/g, '');
}

const bodyEn = clean(parsed.body ?? parsed.bodyEn);
const bodyFr = clean(parsed.bodyFr);

if (!bodyEn || !bodyFr) {
  throw new Error('OpenAI JSON missing body / bodyFr');
}

const max = 2000;
function clip(text) {
  return text.length <= max ? text : `${text.slice(0, max - 1).trimEnd()}…`;
}

return [{ json: { body: clip(bodyEn), bodyFr: clip(bodyFr) } }];
